// Copies the ruby.wasm runtime (CRuby 3.4 + stdlib compiled to WASI) from
// node_modules into public/ruby/ so the live-ruby block loads it SAME-ORIGIN
// (the app's CSP only allows 'self'; works offline). public/ruby/ is
// git-ignored and regenerated by predev/prebuild, so the ~30 MB never enters
// the repo.
import { copyFileSync, existsSync, mkdirSync, statSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const src = join(here, "..", "node_modules", "@ruby", "3.4-wasm-wasi", "dist", "ruby+stdlib.wasm");
const outDir = join(here, "..", "public", "ruby");

if (!existsSync(src)) {
  console.warn("copy-ruby: @ruby/3.4-wasm-wasi not installed — live-ruby blocks will fail to load");
  process.exit(0);
}
mkdirSync(outDir, { recursive: true });
const dest = join(outDir, "ruby+stdlib.wasm");
if (!existsSync(dest) || statSync(dest).size !== statSync(src).size) copyFileSync(src, dest);
console.log(`copy-ruby: ruby+stdlib.wasm → public/ruby/ (${(statSync(src).size / 1e6).toFixed(1)} MB)`);
